export const educationStations=stationContent.map(([name,lesson,reflection],id)=>({id,name,lesson,reflection,status:'draft',items:[
 {title:lesson,body:reflection+'。此為互動示範，個人狀況請由自己的照護團隊說明。'},
 {title:'整理就診問題',body:'把最想了解的一至兩件事記下來，例如想請團隊說明的名詞、流程或聯絡方式，帶到合適的諮詢場合逐項討論。'},
 {title:'我的提問卡',body:'想一想：目前最需要團隊協助說明的是什麼？可以先用自己的話記下問題。本原型不保存提問內容，正式版將由使用者自行選擇是否保存。'}
]}));

